use std::hash::Hash;

#[cfg(feature = "pem")]
use pem::Pem;
use pki_types::CertificateSigningRequestDer;

#[cfg(feature = "pem")]
use crate::ENCODE_CONFIG;
use crate::{
	key_pair::serialize_public_key_der, Certificate, CertificateParams, Error, Issuer, KeyPair,
	PublicKeyData, SignatureAlgorithm,
};
